CREATE TABLE `approval_templates` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`name` VARCHAR(200) NOT NULL,`resource_type` ENUM('task','opportunity_decision') NOT NULL,`status` ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',`current_version` INT UNSIGNED NOT NULL DEFAULT 1,`revision` INT UNSIGNED NOT NULL DEFAULT 1,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`published_by` CHAR(36) CHARACTER SET ascii NULL,`published_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_approval_template_scope`(`organization_id`,`workspace_id`,`status`,`updated_at`),CONSTRAINT `fk_approval_template_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_approval_template_workspace` FOREIGN KEY(`workspace_id`) REFERENCES `workspaces`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_approval_template_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `approval_template_versions` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`template_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`version_number` INT UNSIGNED NOT NULL,`status` ENUM('draft','published','retired') NOT NULL DEFAULT 'draft',`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`published_at` DATETIME(3) NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_approval_template_version`(`template_id`,`version_number`),KEY `idx_approval_version_scope`(`organization_id`,`workspace_id`,`status`),CONSTRAINT `fk_approval_version_template` FOREIGN KEY(`template_id`) REFERENCES `approval_templates`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `approval_template_nodes` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`template_version_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`ordinal` INT UNSIGNED NOT NULL,`name` VARCHAR(120) NOT NULL,`approver_id` CHAR(36) CHARACTER SET ascii NOT NULL,`sla_minutes` INT UNSIGNED NOT NULL,`escalation_assignee_id` CHAR(36) CHARACTER SET ascii NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_approval_node_ordinal`(`template_version_id`,`ordinal`),KEY `idx_approval_node_scope`(`organization_id`,`workspace_id`,`approver_id`),CONSTRAINT `fk_approval_node_version` FOREIGN KEY(`template_version_id`) REFERENCES `approval_template_versions`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_approval_node_approver` FOREIGN KEY(`approver_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_approval_node_escalation` FOREIGN KEY(`escalation_assignee_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `approval_requests` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`template_id` CHAR(36) CHARACTER SET ascii NOT NULL,`template_version_id` CHAR(36) CHARACTER SET ascii NOT NULL,`resource_type` ENUM('task','opportunity_decision') NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`title` VARCHAR(200) NOT NULL,`status` ENUM('pending','approved','rejected','cancelled') NOT NULL DEFAULT 'pending',`current_node_ordinal` INT UNSIGNED NOT NULL DEFAULT 1,`requested_by` CHAR(36) CHARACTER SET ascii NOT NULL,`completed_at` DATETIME(3) NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_approval_request_scope_status`(`organization_id`,`workspace_id`,`status`,`updated_at`),KEY `idx_approval_request_resource`(`organization_id`,`workspace_id`,`resource_type`,`resource_id`),CONSTRAINT `fk_approval_request_template` FOREIGN KEY(`template_id`) REFERENCES `approval_templates`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_approval_request_version` FOREIGN KEY(`template_version_id`) REFERENCES `approval_template_versions`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_approval_request_actor` FOREIGN KEY(`requested_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `approval_node_runs` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`approval_request_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`template_node_id` CHAR(36) CHARACTER SET ascii NOT NULL,`ordinal` INT UNSIGNED NOT NULL,`name` VARCHAR(120) NOT NULL,`approver_id` CHAR(36) CHARACTER SET ascii NOT NULL,`active_approver_id` CHAR(36) CHARACTER SET ascii NOT NULL,`escalation_assignee_id` CHAR(36) CHARACTER SET ascii NOT NULL,`status` ENUM('waiting','pending','approved','rejected','skipped') NOT NULL DEFAULT 'waiting',`due_at` DATETIME(3) NULL,`escalated_at` DATETIME(3) NULL,`decided_by` CHAR(36) CHARACTER SET ascii NULL,`decision_reason` VARCHAR(1000) NULL,`decided_at` DATETIME(3) NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_approval_run_ordinal`(`approval_request_id`,`ordinal`),KEY `idx_approval_run_inbox`(`organization_id`,`workspace_id`,`active_approver_id`,`status`,`due_at`),CONSTRAINT `fk_approval_run_request` FOREIGN KEY(`approval_request_id`) REFERENCES `approval_requests`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_approval_run_node` FOREIGN KEY(`template_node_id`) REFERENCES `approval_template_nodes`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `approval_actions` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`approval_request_id` CHAR(36) CHARACTER SET ascii NOT NULL,`node_run_id` CHAR(36) CHARACTER SET ascii NOT NULL,`action` ENUM('approved','rejected','escalated','cancelled') NOT NULL,`reason` VARCHAR(1000) NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_approval_action_request`(`organization_id`,`workspace_id`,`approval_request_id`,`created_at`),KEY `idx_approval_action_trace`(`trace_id`),CONSTRAINT `fk_approval_action_request` FOREIGN KEY(`approval_request_id`) REFERENCES `approval_requests`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_approval_action_run` FOREIGN KEY(`node_run_id`) REFERENCES `approval_node_runs`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `approval_escalation_jobs` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`approval_request_id` CHAR(36) CHARACTER SET ascii NOT NULL,`node_run_id` CHAR(36) CHARACTER SET ascii NOT NULL,`status` ENUM('queued','leased','succeeded','dead_letter') NOT NULL DEFAULT 'queued',`attempt_count` INT UNSIGNED NOT NULL DEFAULT 0,`available_at` DATETIME(3) NOT NULL,`lease_owner` VARCHAR(120) NULL,`lease_expires_at` DATETIME(3) NULL,`last_error_code` VARCHAR(120) NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_approval_escalation_run`(`node_run_id`),KEY `idx_approval_escalation_claim`(`status`,`available_at`,`lease_expires_at`),CONSTRAINT `fk_approval_escalation_request` FOREIGN KEY(`approval_request_id`) REFERENCES `approval_requests`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_approval_escalation_run` FOREIGN KEY(`node_run_id`) REFERENCES `approval_node_runs`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `approval_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(180) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(128) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_approval_operation`(`actor_id`,`route_key`,`idempotency_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
